mapper.select:
/* 건강기록 대시보드 반려동물별 기록 있는 항목 조회 */ SELECT P.PET_SN , EXISTS (SELECT 1 FROM DAILY_HLTH_RCD R WHERE R.PET_SN = P.PET_SN AND R.DAILY_RCD_IDCT_CD = #{weightCd} AND R.RCD_NVL IS NOT NULL AND R.DEL_YN = 'N') AS WEIGHT_YN , EXISTS (SELECT 1 FROM DAILY_HLTH_RCD R WHERE R.PET_SN = P.PET_SN AND R.DAILY_RCD_IDCT_CD = #{mealCd} AND R.RCD_NVL IS NOT NULL AND R.DEL_YN = 'N' AND R.RCD_DT < DATE_ADD(#{baseYmd}, INTERVAL 1 DAY)) AS MEAL_YN , EXISTS (SELECT 1 FROM DAILY_HLTH_RCD R WHERE R.PET_SN = P.PET_SN AND R.DAILY_RCD_IDCT_CD = #{waterCd} AND R.RCD_NVL IS NOT NULL AND R.DEL_YN = 'N' AND R.RCD_DT < DATE_ADD(#{baseYmd}, INTERVAL 1 DAY)) AS WATER_YN , EXISTS (SELECT 1 FROM DAILY_HLTH_RCD R WHERE R.PET_SN = P.PET_SN AND R.DAILY_RCD_IDCT_CD = #{walkCd} AND R.RCD_NVL IS NOT NULL AND R.DEL_YN = 'N' AND R.RCD_DT < DATE_ADD(#{baseYmd}, INTERVAL 1 DAY)) AS WALK_YN , EXISTS (SELECT 1 FROM DAILY_HLTH_RCD R WHERE R.PET_SN = P.PET_SN AND R.DAILY_RCD_IDCT_CD = #{stoolCd} AND R.DEL_YN = 'N') AS POOP_YN , EXISTS (SELECT 1 FROM CKUP_RCD C JOIN SCHDL S ON S.SCHDL_SN = C.SCHDL_SN WHERE S.PET_SN = P.PET_SN AND S.SCHDL_KND_CD = #{hospitalCd} AND C.CKUP_RCD_STTS_CD = #{completedCd} AND C.DEL_YN = 'N') AS CKUP_YN , EXISTS (SELECT 1 FROM INSP_NVL V JOIN CKUP_RCD C ON C.CKUP_RCD_SN = V.CKUP_RCD_SN JOIN SCHDL S ON S.SCHDL_SN = C.SCHDL_SN WHERE S.PET_SN = P.PET_SN AND S.SCHDL_KND_CD = #{hospitalCd} AND C.CKUP_RCD_STTS_CD = #{completedCd} AND C.DEL_YN = 'N' AND V.DEL_YN = 'N') AS INSP_YN , EXISTS (SELECT 1 FROM PRSC X JOIN CKUP_RCD C ON C.CKUP_RCD_SN = X.CKUP_RCD_SN JOIN SCHDL S ON S.SCHDL_SN = C.SCHDL_SN WHERE S.PET_SN = P.PET_SN AND S.SCHDL_KND_CD = #{hospitalCd} AND C.CKUP_RCD_STTS_CD = #{completedCd} AND C.DEL_YN = 'N' AND X.DEL_YN = 'N') AS PRESC_YN , EXISTS (SELECT 1 FROM CKUP_RCD_ATCH A JOIN ATCH_FILE F ON F.ATCH_FILE_SN = A.ATCH_FILE_SN JOIN CKUP_RCD C ON C.CKUP_RCD_SN = A.CKUP_RCD_SN JOIN SCHDL S ON S.SCHDL_SN = C.SCHDL_SN WHERE S.PET_SN = P.PET_SN AND S.SCHDL_KND_CD = #{hospitalCd} AND C.CKUP_RCD_STTS_CD = #{completedCd} AND C.DEL_YN = 'N' AND A.DEL_YN = 'N') AS ATCH_YN , EXISTS (SELECT 1 FROM OBSRV_ARTCL O WHERE O.PET_SN = P.PET_SN AND O.OBSRV_STTS_CD = #{ongoingCd} AND O.DEL_YN = 'N') AS OBSV_YN , EXISTS (SELECT 1 FROM CKUP_RCD C JOIN SCHDL S ON S.SCHDL_SN = C.SCHDL_SN WHERE S.PET_SN = P.PET_SN AND S.SCHDL_KND_CD = #{hospitalCd} AND C.CKUP_RCD_STTS_CD = #{completedCd} AND C.CKUP_TYPE_CD IN (#{vaccinationCd}, #{regularCd}) AND C.DEL_YN = 'N') AS VACC_YN , EXISTS (SELECT 1 FROM CARE_ARTCL A WHERE A.PET_SN = P.PET_SN AND A.CARE_ZONE_CD = #{dailyZoneCd} AND A.DEL_YN = 'N') AS CARE_YN FROM PET P WHERE P.PET_SN IN
#{petSn}
AND P.DEL_YN = 'N'
